<?php require_once __DIR__.'/../includes/auth.php'; require_role('DONOR');
$d=my_donor($pdo); $st=get('status'); $ur=get('urgency'); $q=get('q'); $from=get('from'); $to=get('to');
$validStatus=['NOTIFIED','ACCEPTED','DECLINED','COMPLETED']; $validUrgency=['CRITICAL','HIGH','NORMAL'];
if(!in_array($st,$validStatus,true)) $st=''; if(!in_array($ur,$validUrgency,true)) $ur='';
$vd=fn($x)=>$x===''||(($o=DateTime::createFromFormat('!Y-m-d',$x)) && $o->format('Y-m-d')===$x);
if(!$vd($from)) $from=''; if(!$vd($to)) $to='';
$sql="SELECT m.*,r.blood_group,r.units_required,r.urgency,r.required_time,r.location,r.notes,r.status AS rstatus,r.location_precise rprec,o.organization_name,o.address AS org_address,o.city AS org_city,o.phone AS org_phone FROM donor_matches m JOIN emergency_requests r USING(request_id) JOIN healthcare_organizations o ON o.organization_id=r.organization_id WHERE m.donor_id=?"; $p=[$d['donor_id']];
if($st){$sql.=' AND m.status=?';$p[]=$st;} if($ur){$sql.=' AND r.urgency=?';$p[]=$ur;}
if($q!==''){$sql.=' AND (o.organization_name LIKE ? OR r.location LIKE ?)';$p[]="%$q%";$p[]="%$q%";}
if($from){$sql.=' AND DATE(r.required_time)>=?';$p[]=$from;} if($to){$sql.=' AND DATE(r.required_time)<=?';$p[]=$to;}
$s=$pdo->prepare($sql." ORDER BY FIELD(r.urgency,'CRITICAL','HIGH','NORMAL'),m.matched_at DESC"); $s->execute($p); $rows=$s->fetchAll();
$title='My Emergency Requests'; $page_intro='Review urgent blood requests sent to you by healthcare organizations.'; require '../includes/header.php'; ?>
<div class="alert">Only accept a request if you are genuinely available and willing to attend. Acceptance does not replace the healthcare organization's eligibility screening.</div>
<form class="filter"><input name="q" placeholder="Search hospital or location" value="<?= h($q) ?>"><select name="status"><option value="">All statuses</option><?php foreach($validStatus as $x): ?><option value="<?= h($x) ?>" <?= $st===$x?'selected':'' ?>><?= h(ucfirst(strtolower($x))) ?></option><?php endforeach; ?></select>
<select name="urgency"><option value="">All urgency levels</option><?php foreach($validUrgency as $x): ?><option value="<?= h($x) ?>" <?= $ur===$x?'selected':'' ?>><?= h(ucfirst(strtolower($x))) ?></option><?php endforeach; ?></select>
<label class="dl">Needed from <input type="date" name="from" value="<?= h($from) ?>"></label><label class="dl">Needed until <input type="date" name="to" value="<?= h($to) ?>"></label><button class="btn">Filter</button> <a class="btn alt" href="emergency_requests.php">Reset</a></form>
<?php foreach($rows as $r): $open=!in_array($r['rstatus'],['CANCELLED','FULFILLED'],true); $expired=$r['required_time']<date('Y-m-d H:i:s'); ?><div class="card"><div class="row"><div><b><?= h($r['organization_name']) ?></b><p><?= badge($r['urgency']) ?> <?= badge($r['status']) ?></p></div><div><span class="muted">Request #<?= (int)$r['request_id'] ?></span></div></div>
<dl class="meta"><div><dt>Blood group needed</dt><dd><b><?= h($r['blood_group']) ?></b></dd></div><div><dt>Units requested</dt><dd><?= h($r['units_required']) ?></dd></div><div><dt>Needed by</dt><dd><?= h($r['required_time']) ?></dd></div><div><dt>Location</dt><dd><?= h($r['location']) ?><?php if($r['distance_km']!==null && $r['distance_km']!==''): ?> <span class="muted">(<?= h(distance_label($r['distance_km'],$d['location_precise']&&$r['rprec'])) ?>)</span><?php endif; ?></dd></div></dl><?php if(!empty($r['notes'])): ?><p><?= nl2br(h($r['notes'])) ?></p><?php endif; ?>
<?php if($r['status']==='ACCEPTED' && $open): ?><div class="alert ok"><b>Where to go:</b> <?= h($r['location']) ?> &middot; <?= h($r['organization_name']) ?>, <?= h($r['org_address']?:$r['org_city']) ?> &middot; Phone: <?= h($r['org_phone']?:'not provided') ?> &middot; Needed by <?= h($r['required_time']) ?></div>
<form method="post" action="response.php" class="inline"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= (int)$r['match_id'] ?>"><button name="action" value="WITHDRAW" class="btn sm alt" data-confirm="Withdraw your acceptance? The organization will be told.">Withdraw acceptance</button></form>
<?php elseif($r['status']==='NOTIFIED' && $open && !$expired): ?><form method="post" action="response.php" class="inline"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= (int)$r['match_id'] ?>"><button name="action" value="ACCEPTED" class="btn sm" data-confirm="Accept this emergency request? Your availability will be set to unavailable until you change it again.">Accept request</button> <select name="reason" aria-label="Reason for declining"><option value="">Reason if declining (optional)</option><option>Not available at that time</option><option>Travelling / out of town</option><option>Too far away</option><option>Feeling unwell</option><option>Other</option></select> <button name="action" value="DECLINED" class="btn sm alt" data-confirm="Decline this request?">Decline</button></form>
<?php elseif($r['rstatus']==='CANCELLED'): ?><span class="muted">The organization cancelled this request. No action is needed; if you had accepted, your availability was restored when you were eligible.</span>
<?php elseif($r['rstatus']==='FULFILLED'): ?><span class="muted">This request has been fulfilled.</span>
<?php elseif($r['status']==='NOTIFIED' && $expired): ?><span class="muted">This request has expired and can no longer be accepted.</span><?php endif; ?></div><?php endforeach; ?>
<?php if(!$rows): ?><div class="empty">No emergency requests match these filters.</div><?php endif; ?>
<?php require '../includes/footer.php'; ?>
